ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_20"] = {
{"s3_c02_party_line_018","any",2,"reg=worker|role=worker|day=10,300|mood=warm",{1,"Spliced a pair between the Crowley farm and the Patterson place - they can ring each other now",2,"A party line, like when I was little",1,"They're on it half the day",2,"Talking about what?",1,"Each other's dogs, mostly, and whose tomatoes are coming in first"}},
{"s3_c02_propane_truck_019","any",2,"reg=worker|role=worker|mood=funny|world=vehicle",{1,"I'm sitting on a truck with twenty-eight hundred gallons of propane",2,"You must be the most popular man in Knox County",1,"Everybody's my friend, nobody will park next to me"}},
{"s3_c02_porch_post_020","any",3,"reg=worker|role=worker|mood=funny|world=building,generator",{1,"Chain the generator to the porch post",2,"They'll just take the porch post",3,"Then chain the porch post to the house",1,"And if they carry off the house, they earned the generator"}},
{"s3_c02_hopper_corn_021","any",2,"reg=worker|role=worker|day=7,300|mood=calm|world=cars",{1,"Freight's been sitting on the siding south of Muldraugh since Friday - forty hopper cars",2,"Of what?",1,"Feed corn",2,"People can eat feed corn",1,"If you soak it in wood ash water and cook it half a day - mamaw called that hominy"}},
{"s3_c02_union_break_022","any",2,"reg=worker|role=worker|mood=funny",{1,"Is this still a union job?",2,"There's no union, there's no job",1,"Then I'm taking my fifteen",2,"You took your fifteen an hour ago",1,"That was my ten"}},
{"s3_c02_leland_gate_023","any",2,"reg=worker|role=worker|day=3,120|mood=sad",{1,"Leland sent every one of us home Friday - go see about your families, he said, I'll lock up",2,"Did he lock up?",1,"Gate was chained when I drove by Monday, his truck was parked inside it",2,"So he locked up"}},
{"s3_c02_register_balance_024","any",2,"reg=worker|role=worker|day=5,300|mood=funny",{1,"Why are you still ringing things up on that register?",2,"Drawer has to balance at the end of the shift",1,"Money's no good, you're taking batteries and deer jerky",2,"Register don't know that, I key it in as miscellaneous"}},
{"s3_c02_tower_float_025","any",3,"reg=worker|role=worker|day=5,200|mood=fear",{1,"Somebody has to climb the tower and look at the float",2,"That's a hundred and forty feet up",3,"I'm scared of heights. A hundred and forty feet...",1,"Either of us goes, we're just guessing. You're the one who knows that float",3,"Then tie a rope on me, and nobody say one word to me on the way up"}},
{"s3_c02_still_on_nights_026","any",2,"reg=worker|role=worker|hour=6,10|mood=funny",{1,"You look dead on your feet",2,"It's eight in the morning, eleven years of nights, my body thinks it's bedtime",1,"World ended, and you're still on nights",2,"World ended on my shift, too, day crew slept right through it"}},
{"s3_c02_box_fan_027","any",2,"reg=worker|role=worker|hour=8,20|mood=warm|world=generator",{1,"We ran the box fan for one hour last night off the generator",2,"Worth the gas?",1,"Best hour of my whole summer, lay on the floor in front of it with my shirt pulled up",2,"Next time you wake me up"}},
{"s3_c02_vcr_christmas_028","any",2,"reg=worker|role=worker|day=10,300|hour=16,5|mood=sad|world=generator",{1,"I want ten minutes of generator tonight, for the VCR",2,"What's on the tape?",1,"Christmas ninety-one, mama's in it about four minutes, mostly fussing at the camera",2,"Ten minutes, then, I'll carry the gas can over myself"}},
{"s3_c02_cattle_guard_029","any",2,"reg=worker|role=worker|mood=calm|world=vehicle,road",{1,"Welded a cattle guard across the front of the flatbed",2,"That's the ugliest thing I ever saw bolted to a truck",1,"Ugly pushes a lot of them out of the road",2,"I didn't say take it off"}},
{"s3_c02_valves_by_hand_030","any",2,"reg=worker|role=worker|day=5,200|hour=4,9|mood=calm|world=building",{1,"Pumps at the plant need power, so I run the gravity feed from the reservoir by hand",2,"How many valves?",1,"Fourteen - open at dawn, closed at dusk, so the tower doesn't run dry overnight",2,"Does anybody even know you're doing it?",1,"Somebody on Main Street turns a faucet and something comes out - that's how they know"}},
{"s3_c02_hardhat_stickers_031","any",2,"reg=worker|role=worker|day=5,300|mood=sad",{1,"Whose hard hat is this with all the stickers?",2,"Ray's, his grandkids stuck those on - one every birthday",1,"There's nine stickers",2,"Put it on the shelf, not in the bin - the shelf"}},
{"s3_c02_siphon_mouth_032","any",2,"reg=worker|role=worker|tmp=fresh|mood=funny",{1,"Who taught you to siphon gas?",2,"Nobody, I saw it once on the news, some story about teenagers",1,"You swallowed about a cup",2,"Every burp I've had since is unleaded"}},
{"s3_c02_underground_tank_033","any",3,"reg=worker|role=worker|tmp=seasoned,veteran|day=5,300|mood=calm",{1,"Underground tanks at the station on 31W still have gas - stick read forty inches",2,"Pumps need power",1,"Pull the fill cap, drop a hose, I've got a hand pump off a fifty-five gallon drum",3,"How loud is a hand pump?",1,"Loud as a man cussing at a hand pump, so not very"}},
{"s3_c02_baby_hum_034","any",2,"reg=worker|role=worker|day=5,300|hour=12,23|mood=warm|world=building,generator",{1,"The baby only goes down when the generator's running",2,"So she's expensive",1,"Half a gallon a nap",2,"Cheapest thing in this house that makes anybody smile"}},
{"s3_c02_windstorm_88_035","any",2,"reg=worker|role=worker|tmp=seasoned,veteran|day=14,300|mood=sad|world=vehicle",{1,"After that windstorm in eighty-eight, we worked nineteen days straight putting poles back up",2,"This is longer",1,"That one had a finish line, somebody's porch light comes on and they wave at the truck",2,"Nobody's waving",1,"No, nobody is"}},
{"s3_c02_meter_reader_036","any",2,"reg=worker|role=worker|day=5,300|mood=calm|world=building",{1,"I read meters in this county sixteen years, I know which houses have a dog, a basement, and a key under a frog",2,"That's a map nobody else has",1,"Folks used to hate seeing me come up the drive",2,"Well, get your clipboard, we love you now"}},
{"s3_c02_operator_log_037","any",1,"reg=worker|role=worker|day=14,300|hour=0,5|mood=calm",{1,"Oh-two-hundred, reservoir at nine feet four - chlorine residual point six",1,"Operator on duty, same as the line above it, same as the whole page above it",1,"Three weeks of one name, looks like a typo"}},
{"s3_c02_carport_cat_038","any",3,"reg=worker|role=worker|day=2,120|mood=funny|world=vehicle",{1,"Used the bucket truck to lift a woman off her carport roof in Riverside",2,"She alright?",1,"Wouldn't climb in till I took her cat first",3,"Well?",1,"Cat took a strip off my wrist, then she climbed in",2,"When we get back to camp, you say cat scratch real loud before anybody sees that"}},
{"s3_c02_big_earl_039","any",2,"reg=worker|role=worker|mood=funny|world=generator",{1,"We named the generator Big Earl",2,"Why Earl?",1,"Loud, drinks too much, and quits right when you need him"}},
{"s3_c02_lunch_pail_040","any",1,"reg=worker|role=worker|day=5,300|mood=sad",{1,"Still got my lunch pail from Friday, never did open it on break",1,"Bologna went bad a long time back, the note's still good, though",1,"Says don't forget the lawn, that's all it says - don't forget the lawn"}},
{"s3_c02_mill_whistle_041","any",2,"reg=worker|role=worker|hour=11,13|mood=calm",{1,"Mill whistle used to go at seven, at noon, and at three-thirty",2,"I miss knowing when lunch was",1,"I don't, my stomach kept the whistle, growls at noon on the dot"}},
{"s3_c02_oxygen_machine_042","any",3,"reg=worker|role=worker|day=3,200|mood=grim|world=building",{1,"Mr. Dunaway's on the oxygen machine, the kind that plugs in the wall",2,"How many hours a day does he need it?",1,"Every one of them, round the clock",3,"Then that's where the gas goes, nobody else gets the fan",2,"Nobody asked for the fan",3,"Somebody was fixing to"}},
{"s3_c02_june_calendar_043","any",2,"reg=worker|role=worker|day=5,300|mood=warm",{1,"Break room calendar's still on June, nobody flipped it",2,"Nobody was here on the first of July?",1,"Everybody was here, we liked the June picture, big green combine out in a wheat field",2,"Leave it on June"}},
{"s3_c02_grocery_ledger_044","any",3,"reg=worker|role=worker|day=4,120|mood=calm|world=door",{1,"Manager at the grocery is handing out the back stock - one sack a family, written in a ledger",2,"Why not just open the doors?",3,"First day he opened the doors, six men took everything and two old ladies went home with nothing",1,"So now it's a ledger, he licks the pencil before every name"}},
{"s3_c02_fence_charger_045","any",2,"reg=worker|role=worker|day=5,300|mood=funny|world=vehicle,fence",{1,"Hooked a cattle fence charger up to a car battery and ran wire around the yard",2,"Does it stop them?",1,"Doesn't bother them one bit, bothered Dwight plenty"}},
{"s3_c02_pine_trees_046","any",2,"reg=worker|role=worker|day=5,300|mood=warm|world=window,trees",{1,"Every rescue rig left in the county comes through my bay sooner or later",2,"What's with the little cardboard pine trees on the mirrors?",1,"Those medics sit in there all night with the windows up",2,"So it smells like Christmas",1,"Smells like something besides what they carried"}},
{"s3_c02_stale_gas_047","any",2,"reg=worker|role=worker|tmp=seasoned,veteran|day=20,300|mood=calm|world=generator",{1,"Gas goes stale in about a month sitting in a can",2,"Then what?",1,"Then it gums up the carburetor and the generator coughs like Papaw in the morning",2,"Can you fix that?",1,"Every bait shop by a boat ramp keeps fuel stabilizer by the register - put it on the list"}},
{"s3_c02_treat_it_hot_048","any",2,"reg=worker|role=worker|tmp=veteran|mood=grim|world=vehicle",{1,"Treat every wire like it's hot",2,"Even now? Nothing's been live in three weeks",1,"Especially now, now nobody's coming with the ambulance"}},
{"s3_c02_breakroom_radio_049","any",3,"reg=worker|role=worker|day=0,4|mood=fear",{1,"Radio in the break room says stay on the job if you're essential personnel",2,"Are we essential?",3,"We run the sewage lift station",1,"Then we're essential - God help us",2,"Nobody ever called us essential before, I'd have liked it on a better week"}},
{"s3_c02_shift_bid_050","any",2,"reg=worker|role=worker|day=14,300|hour=20,5|mood=funny|world=building",{1,"Twenty-two years seniority, I get first pick of the watch",2,"Seniority's gone, the company's gone",1,"Then who's going to stop me taking noon to six?",2,"The sun, noon to six, that roof is a hundred and ten degrees",1,"Put me down for midnight"}},
{"s3_c03_sandbars_001","any",2,"reg=worker|role=worker|tmp=seasoned,veteran|day=5,300|hour=16,22|mood=calm|world=water",{1,"River's down this week - Sandbars are showing off Brandenburg",2,"So we go at night",1,"At night, no lights, on the Ohio? You'll find a barge with your face",2,"Dusk, then",1,"Dusk, and you sit up front and holler log"}},
{"s3_c03_loose_barges_002","any",2,"reg=worker|role=worker|day=5,300|mood=funny|world=window",{1,"A tow of twelve barges broke loose and drifted into the bank below West Point",2,"What's in them?",1,"Six of corn, one smells like fertilizer, one's got a whole house trailer chained on top",2,"Anybody in the trailer?",1,"Curtains are shut, I'm leaving them that way"}},
{"s3_c03_days_off_003","any",2,"reg=worker|role=worker|day=5,300|mood=sad",{1,"I decked on a towboat, twenty-eight days on, fourteen off",2,"When was your off?",1,"That Sunday, bag packed, and a ride coming to the landing in Louisville",2,"Who was the ride?",1,"My wife, bringing both kids and a cooler",1,"Anyway - you want to learn a bowline or don't you?"}},
{"s3_c03_never_tied_up_004","any",2,"reg=worker|role=worker|day=7,300|mood=calm|world=water",{1,"There's a towboat pilot who never tied up, runs up and down between the locks, day and night",2,"Running on what?",1,"Those boats carry enough diesel to run till Christmas",2,"Why won't he land?",1,"Says he's seen what's on the land, river's the only thing left he trusts"}},
{"s3_c03_salt_river_bar_005","any",3,"reg=rescue|role=rescue_firefighter,rescue_medical|day=3,120|mood=fear",{1,"Family out on the sandbar where the Salt River comes into the Ohio - four of them, waving a red shirt",2,"How long they been out there?",3,"Since yesterday, there's three of them standing at the waterline on the West Point side",1,"So we come in on the far side of the bar",2,"And pray the johnboat starts on the first pull"}},
{"s3_c03_bottom_walker_006","any",2,"reg=rescue|role=rescue_firefighter|hour=16,22|mood=funny",{1,"I swear I saw one walking along the bottom off the boat ramp - eight feet down",2,"You saw it?",1,"Clear as day",2,"The Ohio River has never once been clear as day in its whole life",1,"Clear as dusk, then, it was walking"}},
{"s3_c03_shear_pins_007","any",2,"reg=worker|role=worker|day=5,300|mood=calm|world=building",{1,"Took six shear pins for the outboard, snapped four between here and Brandenburg",2,"What's all in the water?",1,"Logs, a lawn chair, a mailbox still on its post",2,"A mailbox floats?",1,"Something was holding it up, I didn't lean over to see what"}},
{"s3_c03_eyeballed_mix_008","any",2,"reg=worker|role=worker|mood=funny",{1,"What ratio did you mix the outboard gas at?",2,"I eyeballed it",1,"You eyeballed it",2,"Looked about right",1,"That's why we paddled the last four miles"}},
{"s3_c03_four_blocks_009","any",3,"reg=rescue|role=rescue_medical,rescue_firefighter|day=7,200|mood=grim",{1,"We tie up under the bridge on the Louisville side and walk four blocks to the hospital pharmacy",2,"Four blocks",1,"Four blocks is nothing",3,"Four blocks of Louisville right now is the Battle of the Bulge",1,"Then we run the four blocks"}},
{"s3_c03_flathead_010","any",2,"reg=worker|role=worker|day=5,300|mood=funny|world=water",{1,"Pulled a flathead catfish off the dock big as a beagle",2,"You're not eating that!",1,"After what's been floating in this river? Ate the whole tail end last night",2,"How do you feel?",1,"Like a man who ate a river catfish - ask me tomorrow"}},
{"s3_c03_houseboat_cove_011","any",2,"reg=worker|role=worker|day=10,300|mood=warm",{1,"Six houseboats rafted up back in the cove, kids cannonballing off the roofs",2,"In that water?",1,"They don't get a say about the water, they got a say about the land",2,"They'll have to come ashore sometime",1,"Not for vegetables, they've got tomatoes growing in kiddie pools on the top decks"}},
{"s3_c03_upstream_012","any",2,"reg=worker|role=worker|tmp=seasoned,veteran|mood=funny",{1,"Ohio runs about three miles an hour through here, upstream, you're fighting it all day",2,"West Point's upstream",1,"West Point's upstream, the gas is downstream, and the Lord loves a joke"}},
{"s3_c03_paddle_in_013","any",2,"reg=rescue|role=rescue_firefighter,rescue_medical|hour=19,5|mood=fear",{1,"If we ever approach a landing by boat, I'd want to look from a distance first",2,"Why not motor right in?",1,"I don't know who's on either bank. I'd rather not advertise we're coming",2,"And check the current before we count on reaching the bank?",1,"Exactly. Paddle harder isn't a substitute for knowing where we could get out"}},
{"s3_c03_lockmaster_014","any",2,"reg=worker|role=worker|day=10,300|mood=warm",{1,"Lockmaster's still up in his tower at the dam, works the gates by hand",2,"Who's even coming through?",1,"Anybody who pulls up and asks polite",2,"What's he charge?",1,"News, wants to know what's upriver, writes every word of it in the lock log"}},
{"s3_c03_second_mortgage_015","any",2,"reg=worker|role=worker|mood=funny|world=water",{1,"Lot of boats on this river named after wives",2,"Mine's named after my mother, the Mae Belle",1,"Mine's named Second Mortgage",2,"Where's she at?",1,"Tied up at the marina - Payment's due the first, I plan on being late"}},
{"s3_c03_pike_pole_016","any",2,"reg=rescue|role=rescue_firefighter|tmp=seasoned,veteran|day=5,300|mood=grim|world=water",{1,"Fifteen years on the river rescue squad, I did recoveries with a pike pole",2,"Hooking them in",1,"Hooking them in for their families, now I use that pole to push them off the bow",2,"Same pole",1,"Same pole - other direction"}},
{"s3_c03_three_flashes_017","any",2,"reg=worker|role=worker|day=5,200|mood=sad",{1,"Ricky took the johnboat across Tuesday night, said he'd flash a light from the Indiana side",2,"He do it?",1,"Somebody flashed a light, three times, around eleven",2,"Was it Ricky?",1,"It was three flashes, that's what he said he'd do"}},
{"s3_c03_gray_boat_018","any",2,"reg=worker,rescue|day=3,120|hour=4,9|mood=fear|world=water,trees",{1,"Army's running a gray patrol boat up the river at dawn - big gun up on the bow",2,"Should we wave them down?",1,"If you've got to wave, wave from inside the tree line",2,"They're our Army",1,"They're somebody's Army, they don't know we're somebody"}},
{"s3_c03_life_jackets_019","any",2,"reg=rescue|role=rescue_firefighter|mood=grim|world=water",{1,"Everybody wears a life jacket, I'm not arguing about it",2,"They're orange, anything on the bank can see us for a mile",1,"Anything on the bank can see you, and I can find you downstream afterward",2,"That's a real cheerful way to put it",1,"I've pulled forty people out of this river, not a one of them had a jacket on"}},
{"s3_c03_indiana_trader_020","any",2,"reg=worker|role=worker|day=10,300|mood=calm",{1,"Fella rows over from the Indiana side at night, trades cigarettes for gasoline",2,"The Army lets him?",1,"The Army doesn't know about him, now you do - so hush"}},
{"s3_c03_trotline_021","any",2,"reg=worker|role=worker|day=7,300|hour=5,9|mood=grim",{1,"Ran the trotline at daylight - forty hooks",2,"What'd we get?",1,"Three channel cats and a work boot",2,"Just the boot?",1,"I didn't look close, I cut that stretch of line loose"}},
{"s3_c03_flood_37_022","any",2,"reg=worker|role=worker|tmp=veteran,seasoned|mood=warm|world=window,road",{1,"My papaw rowed a boat down Main Street in West Point in the thirty-seven flood",2,"Down the street?",1,"Water up to the second floor windows, he tied up to the bank building like it was a dock",2,"And West Point came back",1,"Took years, but he opened a hardware store there in forty-one, and I swept it"}},
{"s3_c03_coil_line_023","any",2,"reg=worker|role=worker|mood=funny",{1,"Coil that line clockwise - clockwise",2,"What's it matter?",1,"It matters when you throw it and it comes off in a knot with one of them on the bank",2,"It's just a rope",1,"It's a line - call it a rope on my boat again and you swim home"}},
{"s3_c03_bank_parade_024","any",2,"reg=worker,rescue|day=3,200|mood=fear|world=water",{1,"They followed us along the bank for two miles",2,"Walking?",1,"Walking right along with the boat, like folks following a float at the Christmas parade",2,"How'd you lose them?",1,"Went around the far side of the island, they just kept walking, right on into the river"}},
{"s3_c03_bug_light_025","any",2,"reg=worker|role=worker|day=5,300|hour=21,3|mood=sad",{1,"Indiana's all lit up tonight",2,"Army lights along the far bank",1,"Somebody over there's got a porch light on, too, yellow bug light",2,"Come in, mosquitoes are eating you alive",1,"Few more minutes - go on without me"}},
{"s3_c03_lock_chamber_026","any",2,"reg=worker|role=worker|day=7,300|mood=funny|world=building",{1,"Best sleep I've had since Friday was tied up inside the lock chamber",2,"Inside the lock?",1,"Concrete walls forty feet up, nothing climbs down to you in there",2,"And if somebody opens the gates?",1,"Then I wake up in a hurry and ten feet lower"}},
{"s3_c03_whistles_027","any",2,"reg=worker,rescue|mood=funny",{1,"On the water, nobody hollers, one whistle, stop - two, back up, three, get down",2,"What's a long one?",1,"A long one means I fell in - come get me",2,"What if I'm the one who falls in?",1,"Then blow long and I'll think it over"}},
{"s3_c03_brandenburg_list_028","any",2,"reg=rescue|role=rescue_medical|day=5,200|mood=calm|world=water,road",{1,"I remember a drugstore a block up from the Brandenburg boat ramp",2,"Wouldn't tell us whether the road or river was usable now",1,"No. Or what's left in the store. I'd want a proper list of what people actually needed",2,"And diapers?",1,"Worth asking about. Just don't tell anybody we've found them yet"}},
{"s3_c03_heron_029","any",2,"reg=worker|role=worker|day=7,300|hour=5,10|mood=warm",{1,"Blue heron's been on that same snag every morning we've gone out",2,"Waiting on fish",1,"Waiting on us, I think, flies off when the motor catches and lands right back",2,"Name him",1,"Already did, he's the harbormaster"}},
{"s3_c03_coffee_can_bail_030","any",2,"reg=worker|role=worker|mood=warm",{1,"Boat's taking water again",2,"Bad?",1,"About a coffee can every four minutes, the Mattingly boy's keeping up",2,"Pay him something",1,"Told him he could steer on the way back, he's bailing like the boat's his"}},
{"s3_c03_river_wall_031","any",2,"reg=rescue|role=rescue_firefighter,rescue_medical|mood=grim|world=water",{1,"Can they swim?",2,"Not that I've seen, they go in and they don't come up",1,"So the river's a wall",2,"The river's a wall that washes them up at every bend a week later"}},
{"s3_c03_postcards_032","any",3,"reg=worker|role=worker|day=7,300|hour=16,22|mood=sad|world=building,water",{1,"Marina store's got ice chests, fishing line, and a bait fridge of nightcrawlers gone to soup",2,"Anything else?",3,"Wire rack of postcards - Greetings from the Ohio River, with a sunset",2,"Take one",3,"To send to who?",2,"Take one anyway"}},
{"s3_c03_fouled_prop_033","any",2,"reg=worker,rescue|day=3,300|mood=fear",{1,"I once heard a boat motor whining with something wrapped on the prop",2,"Weeds?",1,"Not weeds. I wish I hadn't looked over the side",2,"What was it?",1,"I still can't talk about it. Just remember staring at the bank after"}},
{"s3_c03_channel_sixteen_034","any",2,"reg=worker|role=worker|day=7,300|mood=sad",{1,"Marine channel sixteen used to be all tow captains cussing each other out",2,"What's on it now?",1,"One tow captain, cussing at nobody",2,"You ever answer him?",1,"Once, he cussed me out too, best talk I've had all week"}},
{"s3_c03_gravity_valve_035","any",3,"reg=worker|role=worker|tmp=seasoned,veteran|day=5,300|mood=calm|world=building,water",{1,"Marina fuel tank sits up the hill from the dock",2,"Dock pump's electric, though",1,"Crack the valve and gravity does the pumping",3,"Then why hasn't anybody else drained it?",1,"Because nobody else knows the valve's behind the bait fridge"}},
{"s3_c03_game_warden_036","any",2,"reg=worker|role=worker|mood=funny",{1,"Game warden would have a fit, no license, a trotline, and three over the limit",2,"Where's the game warden at?",1,"If he shows up, I'll buy two licenses and hug him on the dock"}},
{"s3_c03_drift_quiet_037","any",3,"reg=worker|role=worker|day=7,300|hour=20,2|mood=warm|world=vehicle",{1,"Last night we cut the motor and drifted from the cove all the way down to the bend",2,"On purpose?",3,"To hear something besides engines and them",1,"Frogs, water on the hull - then the Parker girl started singing real low",2,"Nobody hushed her?",1,"Nobody said one word till the bend"}},
{"s3_c03_jump_on_three_038","any",2,"reg=worker|role=worker|tmp=fresh|mood=fear",{1,"When the bow touches, you jump for the dock with the line - not before",2,"What if I miss?",1,"Then you're wet, and I'm embarrassed, and we try it again",2,"What if one of them's on the dock?",1,"Then you don't jump, that's why you look first - look now"}},
{"s3_c03_towhead_cache_039","any",2,"reg=worker|role=worker|tmp=seasoned,veteran|day=10,300|mood=calm",{1,"Stash half the gas cans on the towhead island below the bend",2,"Why split it?",1,"So if somebody takes the boat, they don't get the gas with it",2,"Who's somebody?",1,"Anybody who isn't in this boat"}},
{"s3_c03_mile_boards_040","any",2,"reg=worker|role=worker|mood=calm|world=water",{1,"How do you know where we are? There's no signs out here",2,"Mile boards on the bank, white ones, every mile of river",1,"Lived here thirty years and never noticed one",2,"You were driving, river folks know the mile, town folks know which feed store"}},
{"s3_c03_empty_johnboat_041","any",2,"reg=worker,rescue|day=3,300|mood=fear",{1,"Johnboat drifting past, nobody in it",2,"Anything aboard?",1,"Cooler - two poles - a thermos, lines still in the water",2,"Grab the cooler",1,"Grab it yourself, the lines are still in the water"}},
{"s3_c03_seasick_medic_042","any",2,"reg=rescue|role=rescue_medical|mood=funny|world=water,trees",{1,"Fourteen years a paramedic, and I get seasick on a river",2,"It's flat water",1,"Tell my stomach it's flat",2,"Pick a tree on the bank and stare it down - don't let it win"}},
{"s3_c03_pull_start_043","any",1,"reg=worker,rescue|mood=fear",{1,"Come on - Choke's out - Primer bulb's hard - come on, you sorry thing",1,"Please, I'll clean your plug - I'll buy you the good oil - please",1,"There, there she goes - good girl, I'm sorry for the sorry thing"}},
{"s3_c03_boat_cook_044","any",1,"reg=worker|role=worker|day=7,300|hour=3,6|mood=sad|world=building",{1,"Every towboat I ever worked had a cook, last one was Miss Bernice",1,"Biscuits at four in the morning for eight men, twenty-eight days running, never missed",1,"About this time she'd bang that pan on the stove - I keep listening for it"}},
{"s3_c03_wake_rule_045","any",3,"reg=worker|role=worker|day=5,300|mood=angry",{1,"You came into the cove at full throttle, your wake swamped the Hardins' canoe",2,"They were fine",3,"They lost a sack of flour and a pair of glasses over the side",2,"There was one on the bank, I wasn't slowing down for it",1,"Next time slow down for the canoe, the one on the bank can't catch a boat"}},
{"s3_c03_sunk_bass_boat_046","any",2,"reg=worker|role=worker|day=5,300|mood=funny|world=building",{1,"Tournament bass boat sank right at the ramp, glitter paint, two hundred horses",2,"How'd it sink?",1,"Somebody left the drain plug out, some things didn't change"}},
{"s3_c03_bank_fisherman_047","any",2,"reg=worker,rescue|day=5,300|mood=sad",{1,"Old man on the bank below the power plant, lawn chair, pole in a forked stick",2,"One of them?",1,"No, he waved, asked if they were biting",2,"And you told him?",1,"Said not much today, he said that's alright, he mostly comes for the sitting"}},
{"s3_c03_radar_night_048","any",2,"reg=worker|role=worker|tmp=veteran,seasoned|hour=21,4|mood=calm|world=water",{1,"Tow captains ran this river at night by radar and a spotlight",2,"We've got neither",1,"We've got a flashlight with a red sock on it, and me - I did it for twenty years",2,"With radar",1,"With radar, hush and watch for the bridge piers"}},
{"s3_c03_marina_ledger_049","any",2,"reg=worker|role=worker|day=10,300|mood=warm|world=water",{1,"Marina owner's letting anybody take a boat that's still tied up - keeps a list of who took which",2,"Why keep a list?",1,"So when the owners come back he can tell them their boat was out saving somebody",2,"Think any of them are coming back?",1,"He dusts the list every morning"}},
{"s3_c03_river_smell_050","any",2,"reg=worker|role=worker|hour=5,9|mood=calm|world=water",{1,"River smells different this morning",2,"Different how?",1,"Like it rained up in Pittsburgh, mud and cold",2,"You can smell Pittsburgh?",1,"I can smell the water coming up, tie everything down twice tonight"}},
{"s3_c04_oyster_crackers_001","any",3,"reg=rescue|role=rescue_clergy,rescue_medical,rescue_firefighter|day=5,300|mood=funny|world=building",{1,"Communion this Sunday is oyster crackers and a can of grape juice out of the pantry",2,"Is that allowed?",1,"Grape juice has been good enough for Baptists a hundred years - the crackers are new",3,"What's the Lord think about oyster crackers?",1,"He's worked with less, pass them down the row"}},
{"s3_c04_lawnmower_confession_002","any",2,"reg=rescue|role=rescue_clergy|day=2,300|mood=warm",{1,"Man with a bite on his shoulder asked me to hear his confession - I'm Methodist, told him I'd do my best",2,"What'd he confess?",1,"Stealing a riding lawnmower off a church lot in nineteen sixty-eight",2,"Nothing worse in sixty years?",1,"Nothing he could think of, wanted it off the books before he went, I told him it was off"}},
{"s3_c04_some_mornings_003","any",2,"reg=rescue|role=rescue_clergy|hour=5,10|mood=calm",{1,"Do you still believe, Pastor?",2,"Some mornings",1,"Which ones?",2,"The ones where somebody's already put the water on to boil before I get up"}},
{"s3_c04_bell_rope_004","any",2,"reg=rescue|role=rescue_clergy|day=3,200|mood=sad",{1,"I tied the bell rope up high so the children can't swing on it",2,"First Sunday it hasn't rung in a long while",1,"A hundred and twelve years, I checked the church history, it rang the Sunday after Pearl Harbor",2,"It'll ring again",1,"I'd like to be the one who unties it, that's all I'll ask for"}},
{"s3_c04_forty_one_names_005","any",2,"reg=rescue|role=rescue_clergy|day=5,300|mood=sad",{1,"Read forty-one names at the service Sunday, didn't have a body for a one of them",2,"Did that matter?",1,"Not to anybody in the pews, they just wanted to hear their person said out loud in a church"}},
{"s3_c04_who_to_tell_006","any",2,"reg=rescue|role=rescue_clergy,rescue_medical|mood=calm",{1,"What do I say to somebody who's bit? I never know what to say",2,"Don't tell them it'll be alright, they know better, and after that they can't trust you",1,"So what, then?",2,"Ask who they want told, then write the name down where they can watch you do it"}},
{"s3_c04_sister_agnes_007","any",2,"reg=rescue|role=rescue_clergy,rescue_medical|mood=warm|world=hot",{1,"Sister Agnes still wears the whole habit, veil and all",2,"In ninety-eight degrees?",1,"She says the Lord knows it's hot, he also knows she promised",2,"She stitched my hand without her glasses on, best stitches I've got on me"}},
{"s3_c04_revival_tent_008","any",2,"reg=rescue|role=rescue_clergy|hour=10,19|mood=funny",{1,"The tent from the August revival is still folded up in the fellowship hall",2,"Put it up - it's shade",1,"It says JESUS SAVES across the top in letters four foot tall",2,"Then it's shade with a word from our sponsor"}},
{"s3_c04_short_prayer_009","any",2,"reg=rescue|role=rescue_clergy,rescue_firefighter,rescue_medical|hour=7,18|mood=funny",{1,"Pastor, say something over us before we go - short - real short",2,"Lord, please",1,"That's it? That's your prayer?",2,"Amen - go on, you're burning daylight"}},
{"s3_c04_creek_baptism_010","any",2,"reg=rescue|role=rescue_clergy|day=7,120|mood=funny|world=water",{1,"We had six baptisms set for the creek on the eighteenth",2,"Do them anyway, people need something to show up for",1,"There's one of them standing waist deep right where I'd stand",2,"Well, that's either an early start or a real bad sign",1,"We'll use the horse trough behind the parsonage"}},
{"s3_c04_hazel_dish_011","any",2,"reg=rescue|role=rescue_clergy|day=5,300|mood=sad",{1,"Forty years, folks brought casseroles to the parsonage, I've still got Hazel Dunn's dish",2,"Supposed to go back to her?",1,"Her name's on masking tape on the bottom, in her hand",2,"Leave the tape on"}},
{"s3_c04_same_work_012","any",2,"reg=rescue|role=rescue_clergy|tmp=veteran,seasoned|mood=grim",{1,"Pastor - is it a sin, what we do to them?",2,"You ever help bury somebody?",1,"My daddy, my uncle Clay",2,"Was that a sin?",1,"No, sir",2,"Same work, son, you're just getting to it a little early"}},
{"s3_c04_red_hymnals_013","any",2,"reg=rescue|role=rescue_clergy|day=10,300|mood=funny",{1,"Don't you burn those hymnals",2,"These are the old red ones, we got the new blue ones in May",1,"Burn the red ones, then, all but mine, mine's got my mother's name written in the front"}},
{"s3_c04_ninth_night_014","any",2,"reg=rescue,worker|day=10,300|hour=20,4|mood=sad",{1,"I prayed every night for nine nights",2,"And the tenth?",1,"I slept"}},
{"s3_c04_bless_in_passing_015","any",3,"reg=rescue|role=rescue_clergy,rescue_medical,rescue_firefighter|mood=funny",{1,"You think anybody's still in there? In them?",2,"I don't know, I bless them as I walk past, just in case",3,"Out loud?",2,"Under my breath, the Lord hears fine, and so do they"}},
{"s3_c04_brother_dale_016","any",2,"reg=rescue,worker|mood=funny",{1,"Brother Dale says it's judgment on Louisville",2,"Then why'd it start down here?",1,"He says he's still working on that part"}},
{"s3_c04_sermon_jokes_017","any",1,"reg=rescue|role=rescue_clergy|day=7,300|mood=sad",{1,"Found my notes for Sunday the eleventh, sermon on patience, three jokes penciled in the margin",1,"One about the line at the post office, one about my brother-in-law and his bass boat",1,"Can't make out the third, I'd give a good deal to know what I thought was funny"}},
{"s3_c04_chapel_door_018","any",2,"reg=rescue|role=rescue_clergy,rescue_medical|day=2,120|mood=grim|world=door",{1,"Hospital chapel was the last room with lights on, forty people in eleven pews",2,"And the door held?",1,"Solid oak, given by the Brooks family in fifty-nine, little brass plaque and all",2,"Somebody ought to write the Brooks family a thank-you note",1,"I did, on the back of a visitor card - it's still in my pocket"}},
{"s3_c04_rain_prayer_019","any",2,"reg=rescue,worker|day=5,300|mood=funny|world=rain",{1,"The Baptist bunch prayed for rain Wednesday night",2,"And it rained Thursday",1,"Rained so hard the cistern ran over and the Methodists' tarp came down on their heads",2,"So now the Methodists are praying for the Baptists to quit"}},
{"s3_c04_this_child_020","any",2,"reg=rescue|role=rescue_clergy|tmp=veteran,seasoned|day=7,300|mood=grim",{1,"I've done six hundred funerals, near about",2,"What's different now?",1,"I used to know the family and the name and the hymn they wanted",2,"And these days?",1,"Now I say this child of God, and I make that cover everything"}},
{"s3_c04_organ_generator_021","any",2,"reg=rescue,worker|day=7,300|mood=funny|world=generator",{1,"Deacon wants to hook the generator up to the organ for Sunday",2,"The whole county would hear that organ",1,"That's what he said, like it was a selling point",2,"Tell him one hymn on the piano, and the piano plays soft"}},
{"s3_c04_sitting_is_fine_022","any",2,"reg=worker,rescue|day=3,300|mood=angry",{1,"Don't pray over my brother, I mean it, not one word",2,"Alright, I won't",1,"God had forty years to say something to him and picked this week to go quiet",2,"Alright, I'll just sit, then - is sitting alright?",1,"Sitting's fine"}},
{"s3_c04_good_fences_023","any",2,"reg=rescue|role=rescue_clergy|day=5,300|mood=warm|world=fence",{1,"Little Timmy Ashby asked me if Heaven has any of them in it",2,"Lord, what'd you come up with?",1,"I said no, he asked how they keep them out, I said real good fences",2,"Fences",1,"That's what his daddy's been building all week, it made perfect sense to him"}},
{"s3_c04_half_doses_024","any",2,"reg=worker,rescue|role=worker,rescue_medical|day=7,300|mood=calm",{1,"I've split every blood pressure pill in the bag, half doses for everybody",2,"Is half a dose any good?",1,"Half a dose on a Thursday beats a whole one you haven't got"}},
{"s3_c04_phenobarbital_025","any",2,"reg=worker,rescue|role=worker,rescue_medical|day=5,300|mood=calm",{1,"Somebody cleaned the phenobarbital out of the Rosewood drugstore - nothing else - just that",2,"Who takes that?",1,"Seizures, two people filled it with me - old Mr. Kersey, and a little girl named Amber",2,"Mr. Kersey was ninety-one",1,"So Amber's people are alive, and they're walking distance from Rosewood"}},
{"s3_c04_lazy_pills_026","any",2,"reg=worker,rescue|role=worker,rescue_medical|day=10,300|mood=funny",{1,"Expiration date on this bottle says June",2,"Throw it out",1,"It didn't turn to poison on the first of July - it just got a little lazy, most of them do"}},
{"s3_c04_sugar_morphine_027","any",2,"reg=worker,rescue|role=worker,rescue_medical|mood=funny",{1,"Before I locked up, I filled a stock bottle with sugar pills and set it on the counter marked morphine",2,"Did they take it?",1,"First night, somebody out there is real calm and real disappointed"}},
{"s3_c04_still_doc_028","any",2,"reg=worker,rescue|role=worker,rescue_medical|mood=warm",{1,"Folks still call me Doc",2,"You're a pharmacist",1,"Told them that for thirty-one years, they'd nod and pull up their sleeve to show me the rash anyway"}},
{"s3_c04_sugar_salt_water_029","any",2,"reg=worker,rescue|role=worker,rescue_medical|day=5,300|mood=calm|world=building",{1,"I remember children getting sick with diarrhea at a shelter",2,"What could you do for them?",1,"Try to find proper rehydration supplies and qualified help. I wouldn't trust a recipe half remembered in a panic",2,"People kept telling you sugar, salt and water?",1,"They did. Getting quantities wrong matters, and I couldn't promise a homemade drink would keep every child alive"}},
{"s3_c04_glovebox_nitro_030","any",2,"reg=worker,rescue|role=worker,rescue_medical|day=5,120|mood=fear",{1,"Where's Harold been keeping his heart pills?",2,"Glovebox of his truck - since Friday",1,"Nitro tablets in a glovebox in July, they're about as strong as breath mints by now",2,"So what do we do?",1,"Find him a fresh bottle before his chest finds out"}},
{"s3_c04_april_baby_031","any",2,"reg=worker,rescue|role=worker,rescue_medical|day=10,300|mood=calm",{1,"Three women asked me for birth control pills this week",2,"That's what we're spending a run on?",1,"You want to deliver a baby in a hay barn next April with no hospital? Then yes - it's on the list"}},
{"s3_c04_glenda_knife_032","any",2,"reg=worker,rescue|role=worker,rescue_medical|day=5,300|mood=sad",{1,"Glenda's glasses are still hanging on their chain off the register",2,"Your tech?",1,"Nineteen years she counted pills by fives with a butter knife - faster than me",2,"You okay over there?",1,"I'm fine, it's just the, the tray, I can't count on the tray right without her knife"}},
{"s3_c04_star_by_name_033","any",2,"reg=worker,rescue|role=worker,rescue_medical|tmp=seasoned,veteran|day=7,300|mood=grim",{1,"Which of these can people do without?",2,"Thyroid, a while - Cholesterol, forever - Seizure pills and insulin, not a day",1,"And the heart ones?",2,"Depends on the heart, I'm putting a star by the ones where it doesn't depend"}},
{"s3_c04_goldfish_box_034","any",2,"reg=worker,rescue|role=worker,rescue_medical|day=10,300|mood=funny",{1,"Pet store in Muldraugh has fish antibiotics, same pills as people get, with a goldfish on the box",2,"Is that safe?",1,"Same powder as the capsules I sold you last winter for your sinuses - minus the goldfish"}},
{"s3_c04_roll_call_035","any",2,"reg=worker|role=worker|day=5,300|hour=6,10|mood=sad",{1,"I still call roll every morning - habit",2,"Everybody here?",1,"Everybody who's here is here"}},
{"s3_c04_fire_drill_line_036","any",2,"reg=worker|role=worker|mood=funny|world=door",{1,"Line up at the door, hand on the shoulder in front of you - fire drill rules",2,"And the kids did it?",1,"Third graders did it in forty seconds flat, the grown men took two minutes and argued"}},
{"s3_c04_everybody_passes_037","any",2,"reg=worker|role=worker|day=7,300|hour=4,11|mood=warm",{1,"I've still got report cards for fourth period, never got them in the mail",2,"What'd you give them?",1,"Everybody passes, I decided this morning",2,"Even the Bledsoe boy?",1,"Especially the Bledsoe boy, he sleeps on a gym floor and hasn't cried once where the little ones can see"}},
{"s3_c04_hominy_spelling_038","any",2,"reg=worker|role=worker|day=10,300|mood=funny",{1,"Spelling words this week come off the can labels, peaches, beans, hominy",2,"Hominy's a hard one",1,"Hominy is a fifth-grade word, they'll survive hominy"}},
{"s3_c04_gym_whistles_039","any",2,"reg=worker|role=worker|mood=funny|world=building",{1,"Every kid's got a buddy, you lose yours, you tell me",2,"Let you know how? Hollering brings them",1,"Handed out the whistles from the gym closet, one tweet means I lost my buddy",2,"And two?",1,"Two means I found a frog, and Miss Carter is taking your whistle"}},
{"s3_c04_earth_science_040","any",2,"reg=worker|role=worker|day=3,300|mood=sad",{1,"The kids asked me why the dead get back up",2,"What'd you say to that?",1,"I've taught earth science twenty-two years, answering why is the whole job",2,"So what was the answer?",1,"I said I don't know, first time I ever said it to a class and meant it"}},
{"s3_c04_hardesty_rule_041","any",2,"reg=worker|role=worker|day=14,300|mood=sad",{1,"Principal Hardesty had one rule, nobody leaves the building till every child's been picked up",2,"It's been three weeks",1,"Four children still waiting on a ride",2,"So nobody leaves",1,"Nobody leaves"}},
{"s3_c04_lice_shampoo_042","any",2,"reg=worker|role=worker|day=5,300|mood=funny",{1,"School nurse's office, ice packs, forty - tweezers, two, lice shampoo, a whole case",2,"What do we need lice shampoo for?",1,"You just scratched your head twice while I was reading - so don't get proud"}},
{"s3_c04_lorene_beans_043","any",2,"reg=worker|role=worker|day=5,300|mood=warm|world=building",{1,"Miss Lorene ran the lunch line twenty years, now she feeds ninety people out of the same kitchen",2,"What's she serving?",1,"Same as it ever was, whatever's in the can, and you will eat your green beans",2,"Kids still fighting her on the beans?",1,"Grown men fight her on the beans now, grown men lose"}},
{"s3_c04_senior_portraits_044","any",2,"reg=worker|role=worker|day=7,300|mood=warm|world=door",{1,"Senior portraits came back from the photographer the week before all this - box of them in the office",2,"What are you doing with them?",1,"When one of those kids walks through the door, I hand them their picture",2,"Anybody come by for one yet?",1,"Three, the Pruett girl laughed at her hair so hard she had to sit down"}},
{"s3_c04_lounge_rule_045","any",3,"reg=worker|role=worker|day=7,300|mood=funny",{1,"Teachers' lounge had one rule, nobody talks about work at lunch",2,"What'd you all talk about?",3,"Work",1,"New rule, nobody talks about them at supper",2,"And what do we talk about?",3,"Them"}},
{"s3_c04_substitute_046","any",2,"reg=worker|role=worker|tmp=fresh|day=5,300|mood=funny",{1,"I was a substitute, two weeks on the list",2,"And now you're the whole faculty",1,"I still don't know where they keep the good chalk"}},
{"s3_c04_gym_chart_047","any",2,"reg=worker|role=worker|day=5,300|mood=calm|world=building",{1,"At the gym I kept a chart. Every name, every pill, what time they took it",2,"Sounded like a seating chart",1,"It was that too. Asked them not to trade cots without telling me, so I could find the right person"}},
}
